            "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ جَهَنَّمَ وَمِنْ عَذَابِ الْقَبْرِ وَمِنْ فِتْنَةِ الْمَحْيَا وَالْمَمَاتِ وَمِنْ شَرِّ فِتْنَةِ الْمَسِيحِ الدَّجَّالِ",
            "আল্লাহুম্মা ইন্নী আউযু বিকা মিন আযাবি জাহান্নাম, ওয়া মিন আযাবিল কবর, ওয়া মিন ফিতনাতিল মাহইয়া ওয়াল মামাত, ওয়া মিন শাররি ফিতনাতিল মাসীহিদ দাজ্জাল।",
            "হে আল্লাহ! জাহান্নামের শাস্তি, কবরের শাস্তি, জীবন-মৃত্যুর ফিতনা এবং দাজ্জালের ফিতনার অনিষ্ট থেকে তোমার আশ্রয় চাই।",
            "সহিহ মুসলিম ৫৮৮", "শেষ তাশাহহুদের পর, সালাম ফেরানোর আগে", "১ বার বা দোয়ার সময়", "নবী ﷺ এ চার বিষয় থেকে আশ্রয় চাইতে নির্দেশ দিয়েছেন।", "সহিহ", sourceUrl="https://sunnah.com/muslim:588"),

        // DAILY, SLEEP, WAKE
        dua(11, "ঘুমানোর সময়ের দোয়া", CATEGORY_SLEEP,
            "بِاسْمِكَ اللَّهُمَّ أَمُوتُ وَأَحْيَا",
            "বিসমিকা আল্লাহুম্মা আমূতু ওয়া আহইয়া।",
            "হে আল্লাহ! তোমার নামেই আমি মৃত্যুবরণ করি এবং জীবিত হই। এখানে ঘুমকে সাময়িক মৃত্যুর সঙ্গে তুলনা করা হয়েছে।",
            "সহিহ বুখারি ৬৩২৪", "ঘুমাতে যাওয়ার সময়", "১ বার", "ঘুমানোর আগে নবী ﷺ এ দোয়া পড়তেন।", "সহিহ", sourceUrl="https://sunnah.com/bukhari:6324"),
        dua(12, "ঘুম থেকে জেগে ওঠার দোয়া", CATEGORY_WAKE,
            "الْحَمْدُ لِلَّهِ الَّذِي أَحْيَانَا بَعْدَ مَا أَمَاتَنَا وَإِلَيْهِ النُّشُورُ",
            "আলহামদু লিল্লাহিল্লাযী আহইয়ানা বা‘দা মা আমাতানা, ওয়া ইলাইহিন নুশূর।",
            "সমস্ত প্রশংসা আল্লাহর, যিনি আমাদের মৃত্যুর (ঘুমের) পর জীবিত করেছেন; আর তাঁর কাছেই পুনরুত্থান।",
            "সহিহ বুখারি ৬৩১২", "ঘুম থেকে জাগার পর", "১ বার", "জাগ্রত হওয়ার সময় নবী ﷺ এ দোয়া পড়তেন।", "সহিহ", sourceUrl="https://sunnah.com/bukhari:6312"),
        dua(13, "ঘর থেকে বের হওয়ার দোয়া", CATEGORY_HOME,
            "بِسْمِ اللَّهِ تَوَكَّلْتُ عَلَى اللَّهِ وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ",
            "বিসমিল্লাহি, তাওয়াক্কালতু আলাল্লাহি, ওয়া লা হাওলা ওয়া লা কুওয়াতা ইল্লা বিল্লাহ।",
            "আল্লাহর নামে বের হচ্ছি; আল্লাহর ওপর ভরসা করলাম। আল্লাহর সাহায্য ছাড়া কোনো শক্তি ও সামর্থ্য নেই।",
            "সুনান আবু দাউদ ৫০৯৫; জামে তিরমিযি ৩৪২৬", "ঘর থেকে বের হওয়ার সময়", "১ বার", "হাদিসে হিদায়াত, যথেষ্টতা ও সুরক্ষার সুসংবাদ এসেছে।", "হাসান/সহিহ হিসেবে গ্রেডকৃত", sourceUrl="https://sunnah.com/abudawud:5095"),
        dua(14, "ঘরে প্রবেশের আদব", CATEGORY_HOME,
            "بِسْمِ اللَّهِ وَلَجْنَا وَبِسْمِ اللَّهِ خَرَجْنَا وَعَلَى اللَّهِ رَبِّنَا تَوَكَّلْنَا",
            "বিসমিল্লাহি ওয়ালাজনা, ওয়া বিসমিল্লাহি খারাজনা, ওয়া আলাল্লাহি রব্বিনা তাওয়াক্কালনা।",
            "আল্লাহর নামে আমরা প্রবেশ করলাম, আল্লাহর নামেই বের হলাম এবং আমাদের রব আল্লাহর ওপরই ভরসা করলাম। এরপর ঘরের লোকদের সালাম দেওয়া।",
            "সুনান আবু দাউদ ৫০৯৬ (ঘরে প্রবেশের বর্ণনা)", "ঘরে প্রবেশের সময়", "প্রবেশের সময়", "ঘরে প্রবেশের সময় আল্লাহর নাম নেওয়া ও সালাম দেওয়ার শিক্ষা রয়েছে।", "হাদিসের বর্ণনা; সনদ-গ্রেড যাচাইসহ পড়ুন", sourceUrl="https://sunnah.com/abudawud:5096"),
        dua(15, "টয়লেটে প্রবেশের দোয়া", CATEGORY_TOILET,
            "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْخُبُثِ وَالْخَبَائِثِ",
            "আল্লাহুম্মা ইন্নী আউযু বিকা মিনাল খুবুছি ওয়াল খাবা-ইছ।",
            "হে আল্লাহ! অপবিত্র পুরুষ ও নারী শয়তান থেকে তোমার আশ্রয় চাই।",
            "সহিহ বুখারি ১৪২; সহিহ মুসলিম ৩৭৫", "টয়লেটে প্রবেশের আগে", "১ বার", "প্রবেশের আগে এ দোয়া পড়ার সুন্নাহ রয়েছে।", "সহিহ", sourceUrl="https://sunnah.com/bukhari:142"),
        dua(16, "মসজিদে প্রবেশের দোয়া", CATEGORY_MOSQUE,
            "اللَّهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ",
            "আল্লাহুম্মাফতাহ লী আবওয়াবা রহমাতিক।",
