            "সহিহ মুসলিম ৭১৩", "মসজিদে প্রবেশের সময়", "১ বার", "মসজিদে প্রবেশের দোয়া হিসেবে বর্ণিত।", "সহিহ", sourceUrl="https://sunnah.com/muslim:713"),
        dua(17, "মসজিদ থেকে বের হওয়ার দোয়া", CATEGORY_MOSQUE,
            "اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ فَضْلِكَ",
            "আল্লাহুম্মা ইন্নী আসআলুকা মিন ফাদলিক।",
            "হে আল্লাহ! আমি তোমার অনুগ্রহ প্রার্থনা করছি।",
            "সহিহ মুসলিম ৭১৩", "মসজিদ থেকে বের হওয়ার সময়", "১ বার", "মসজিদ থেকে বের হওয়ার দোয়া হিসেবে বর্ণিত।", "সহিহ", sourceUrl="https://sunnah.com/muslim:713"),
        dua(18, "খাওয়ার শুরুতে বিসমিল্লাহ", CATEGORY_FOOD,
            "بِسْمِ اللَّهِ",
            "বিসমিল্লাহ।",
            "আল্লাহর নামে। খাওয়ার শুরুতে আল্লাহর নাম নিতে হবে। ভুলে গেলে মনে পড়ার পর ‘বিসমিল্লাহি আওয়ালাহু ওয়া আখিরাহু’ বলা যায়।",
            "সহিহ বুখারি ৫৩৭৬; সুনান আবু দাউদ ৩৭৬৭", "খাবার শুরু করার আগে", "শুরুতে ১ বার", "খাওয়ার সময় ডান হাত ব্যবহার ও নিজের সামনে থেকে খাওয়ার নির্দেশনাও একই হাদিসে আছে।", "সহিহ", sourceUrl="https://sunnah.com/bukhari:5376"),
        dua(20, "ওজুর পরের সাক্ষ্য", CATEGORY_WUDU,
            "أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ",
            "আশহাদু আল্লা ইলাহা ইল্লাল্লাহু ওয়াহদাহু লা শারীকা লাহু, ওয়া আশহাদু আন্না মুহাম্মাদান আবদুহু ওয়া রাসূলুহ।",
            "আমি সাক্ষ্য দিচ্ছি, আল্লাহ ছাড়া কোনো সত্য উপাস্য নেই; তিনি এক, তাঁর কোনো শরিক নেই। আরও সাক্ষ্য দিচ্ছি, মুহাম্মদ ﷺ তাঁর বান্দা ও রাসুল।",
            "সহিহ মুসলিম ২৩৪", "ওজু সম্পন্ন করার পর", "১ বার", "হাদিসে জান্নাতের আট দরজা খুলে দেওয়ার ফজিলত এসেছে।", "সহিহ", sourceUrl="https://sunnah.com/muslim:234"),

        // PARENTS & FAMILY
        dua(21, "পিতা-মাতার জন্য দোয়া", CATEGORY_PARENTS,
