            "হে আমার রব! তাঁদের উভয়ের প্রতি দয়া কর, যেমন তাঁরা শৈশবে আমাকে লালন-পালন করেছেন।",
            "কুরআন ১৭:২৪", "পিতা-মাতার জন্য দোয়া করার সময়", "যেকোনো সময়", "এটি পিতা-মাতার প্রতি বিনয় ও দয়ার কুরআনি দোয়া।", "কুরআনের আয়াত", sourceUrl="https://quran.com/17/24"),
        dua(22, "নিজের ও পিতা-মাতার ক্ষমার দোয়া", CATEGORY_PARENTS,
            "رَبَّنَا اغْفِرْ لِي وَلِوَالِدَيَّ وَلِلْمُؤْمِنِينَ يَوْمَ يَقُومُ الْحِسَابُ",
            "রব্বানাগফির লী ওয়া লিওয়ালিদাইয়া ওয়া লিল মু’মিনীনা ইয়াওমা ইয়াকূমুল হিসাব।",
            "হে আমাদের রব! আমাকে, আমার পিতা-মাতাকে এবং মুমিনদের হিসাব প্রতিষ্ঠার দিনে ক্ষমা কর।",
            "কুরআন ১৪:৪১", "দোয়ার সময়", "যেকোনো সময়", "ইবরাহিম (আ.)-এর কুরআনি দোয়া।", "কুরআনের আয়াত", sourceUrl="https://quran.com/14/41"),
        dua(23, "সৎ জীবনসঙ্গী ও সন্তানদের জন্য দোয়া", CATEGORY_FAMILY,
            "رَبَّنَا هَبْ لَنَا مِنْ أَزْوَاجِنَا وَذُرِّيَّاتِنَا قُرَّةَ أَعْيُنٍ وَاجْعَلْنَا لِلْمُتَّقِينَ إِمَامًا",
            "রব্বানা হাব লানা মিন আযওয়াজিনা ওয়া যুররিয়্যাতিনা কুররাতা আ‘ইউনিওঁ ওয়াজ‘আলনা লিল মুত্তাকীনা ইমামা।",
            "হে আমাদের রব! আমাদের জীবনসঙ্গী ও সন্তানদের আমাদের চোখের প্রশান্তি বানাও এবং আমাদের মুত্তাকিদের আদর্শ কর।",
            "কুরআন ২৫:৭৪", "পরিবারের কল্যাণের জন্য", "যেকোনো সময়", "সৎ পরিবার ও তাকওয়ার আদর্শ হওয়ার দোয়া।", "কুরআনের আয়াত", sourceUrl="https://quran.com/25/74"),

        // RABBANA QURAN DUAS
        dua(24, "আমল কবুলের দোয়া", CATEGORY_RABBANA,
            "رَبَّنَا تَقَبَّلْ مِنَّا إِنَّكَ أَنْتَ السَّمِيعُ الْعَلِيمُ",
            "রব্বানা তাকাব্বাল মিন্না, ইন্নাকা আন্তাস সামীউল আলীম।",
            "হে আমাদের রব! আমাদের পক্ষ থেকে কবুল কর; নিশ্চয়ই তুমি সর্বশ্রোতা, সর্বজ্ঞ।",
            "কুরআন ২:১২৭", "ইবাদত ও সৎকাজের পর", "যেকোনো সময়", "ইবরাহিম ও ইসমাইল (আ.)-এর দোয়া।", "কুরআনের আয়াত", sourceUrl="https://quran.com/2/127"),
        dua(25, "হেদায়াতের পর অন্তর অবিচল রাখার দোয়া", CATEGORY_RABBANA,
            "رَبَّنَا لَا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا وَهَبْ لَنَا مِنْ لَدُنْكَ رَحْمَةً إِنَّكَ أَنْتَ الْوَهَّابُ",
            "রব্বানা লা তুযিগ কুলুবানা বা‘দা ইয হাদাইতানা, ওয়া হাব লানা মিল্লাদুনকা রহমাহ; ইন্নাকা আন্তাল ওয়াহহাব।",
            "হে আমাদের রব! হেদায়াত দেওয়ার পর আমাদের অন্তরকে বক্র করো না; তোমার পক্ষ থেকে আমাদের রহমত দান কর। নিশ্চয়ই তুমি মহাদাতা।",
            "কুরআন ৩:৮", "ঈমানের ওপর অবিচল থাকার দোয়া", "যেকোনো সময়", "কুরআনে মুমিনদের এ দোয়া শেখানো হয়েছে।", "কুরআনের আয়াত", sourceUrl="https://quran.com/3/8"),

        // PROPHETS' DUAS
        dua(27, "ইউনুস (আ.)-এর দোয়া", CATEGORY_PROPHETS,
            "لَا إِلَهَ إِلَّا أَنْتَ سُبْحَانَكَ إِنِّي كُنْتُ مِنَ الظَّالِمِينَ",
            "লা ইলাহা ইল্লা আন্তা সুবহানাকা ইন্নী কুনতু মিনায যালিমীন।",
            "তুমি ছাড়া কোনো সত্য উপাস্য নেই; তুমি পবিত্র। নিশ্চয়ই আমি জালিমদের অন্তর্ভুক্ত ছিলাম।",
            "কুরআন ২১:৮৭", "কষ্ট, অনুতাপ ও দোয়ার সময়", "যেকোনো সময়", "ইউনুস (আ.)-এর দোয়া; পরের আয়াতে আল্লাহ তাঁর দোয়া কবুলের কথা বলেন।", "কুরআনের আয়াত", sourceUrl="https://quran.com/21/87"),
        dua(28, "মূসা (আ.)-এর কল্যাণ প্রার্থনা", CATEGORY_PROPHETS,
            "رَبِّ إِنِّي لِمَا أَنْزَلْتَ إِلَيَّ مِنْ خَيْرٍ فَقِيرٌ",
            "রব্বি ইন্নী লিমা আনযালতা ইলাইয়্যা মিন খাইরিন ফাকীর।",
            "হে আমার রব! তুমি আমার প্রতি যে কল্যাণই নাজিল করবে, আমি তার মুখাপেক্ষী।",
            "কুরআন ২৮:২৪", "প্রয়োজন ও কল্যাণের জন্য দোয়া", "যেকোনো সময়", "মূসা (আ.)-এর কুরআনি দোয়া।", "কুরআনের আয়াত", sourceUrl="https://quran.com/28/24"),
        dua(29, "আদম (আ.)-এর তাওবার দোয়া", CATEGORY_PROPHETS,
            "رَبَّنَا ظَلَمْنَا أَنْفُسَنَا وَإِنْ لَمْ تَغْفِرْ لَنَا وَتَرْحَمْنَا لَنَكُونَنَّ مِنَ الْخَاسِرِينَ",
            "রব্বানা যালামনা আনফুসানা, ওয়া ইল্লাম তাগফির লানা ওয়া তারহামনা লানাকূনান্না মিনাল খাসিরীন।",
            "হে আমাদের রব! আমরা নিজেদের প্রতি জুলুম করেছি। তুমি যদি আমাদের ক্ষমা না কর এবং দয়া না কর, তবে আমরা অবশ্যই ক্ষতিগ্রস্ত হব।",
            "কুরআন ৭:২৩", "তাওবা ও অনুতাপের সময়", "যেকোনো সময়", "আদম ও হাওয়া (আ.)-এর কুরআনি দোয়া।", "কুরআনের আয়াত", sourceUrl="https://quran.com/7/23"),

        // TAUBA, AKHIRAH, DISTRESS, ILLNESS, DEBT
        dua(30, "ইস্তিগফার ও তাওবা", CATEGORY_TAWBAH,
            "أَسْتَغْفِرُ اللَّهَ وَأَتُوبُ إِلَيْهِ",
            "আস্তাগফিরুল্লাহা ওয়া আতূবু ইলাইহি।",
            "আমি আল্লাহর কাছে ক্ষমা চাই এবং তাঁর কাছেই তাওবা করি।",
            "সহিহ বুখারি ৬৩০৭; সহিহ মুসলিম ২৭০২-এ দৈনিক বহুবার ইস্তিগফারের বর্ণনা", "নিয়মিত, বিশেষত ভুলের পর", "বারবার", "নবী ﷺ নিজেও নিয়মিত ইস্তিগফার ও তাওবা করতেন।", "সহিহ", sourceUrl="https://sunnah.com/bukhari:6307"),
        dua(31, "দুশ্চিন্তা, অক্ষমতা ও ঋণের ভার থেকে আশ্রয়", CATEGORY_DISTRESS,
            "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ وَالْعَجْزِ وَالْكَسَلِ وَالْجُبْنِ وَالْبُخْلِ وَضَلَعِ الدَّيْنِ وَغَلَبَةِ الرِّجَالِ",
            "আল্লাহুম্মা ইন্নী আউযু বিকা মিনাল হাম্মি ওয়াল হাযানি, ওয়াল আজজি ওয়াল কাসালি, ওয়াল জুবনি ওয়াল বুখলি, ওয়া দালা‘ইদ দাইনি ওয়া গালাবাতির রিজাল।",
            "হে আল্লাহ! দুশ্চিন্তা ও বিষণ্নতা, অক্ষমতা ও অলসতা, ভীরুতা ও কৃপণতা, ঋণের ভার এবং মানুষের দমন থেকে তোমার আশ্রয় চাই।",
            "সহিহ বুখারি ৬৩৬৯", "যেকোনো সময় দোয়া করা যায়", "যেকোনো সময়", "নবী ﷺ এ বিষয়গুলো থেকে আশ্রয় চাইতেন।", "সহিহ", sourceUrl="https://sunnah.com/bukhari:6369"),
        dua(32, "অসুস্থ ব্যক্তির জন্য শিফার দোয়া", CATEGORY_ILLNESS,
            "اللَّهُمَّ رَبَّ النَّاسِ أَذْهِبِ الْبَأْسَ اشْفِ أَنْتَ الشَّافِي لَا شِفَاءَ إِلَّا شِفَاؤُكَ شِفَاءً لَا يُغَادِرُ سَقَمًا",
            "আল্লাহুম্মা রব্বান-নাস, আযহিবিল বা’স, ইশফি আন্তাশ-শাফী, লা শিফা’আ ইল্লা শিফাউক, শিফা’আন লা ইউগাদিরু সাকামা।",
            "হে মানুষের রব আল্লাহ! কষ্ট দূর কর, আরোগ্য দান কর; তুমিই আরোগ্যদাতা। তোমার আরোগ্য ছাড়া কোনো আরোগ্য নেই—এমন আরোগ্য দাও যা কোনো রোগ অবশিষ্ট রাখে না।",
            "সহিহ বুখারি ৫৭৪৩; সহিহ মুসলিম ২১৯১", "অসুস্থ ব্যক্তির জন্য দোয়া করার সময়", "দোয়া হিসেবে পড়া যায়", "রোগমুক্তির জন্য নবী ﷺ এ দোয়া করতেন। চিকিৎসার বিকল্প নয়।", "সহিহ", sourceUrl="https://sunnah.com/bukhari:5743"),
        dua(33, "ঋণ ও মানুষের কাছে মুখাপেক্ষিতা থেকে আশ্রয়", CATEGORY_DEBT,
            "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْمَأْثَمِ وَالْمَغْرَمِ",
            "আল্লাহুম্মা ইন্নী আউযু বিকা মিনাল মা’ছামি ওয়াল মাগরাম।",
            "হে আল্লাহ! পাপ ও ঋণের বোঝা থেকে তোমার আশ্রয় চাই।",
            "সহিহ বুখারি ৮৩২; সহিহ বুখারি ৬৩৬৮", "দোয়ার সময়", "যেকোনো সময়", "নবী ﷺ ঋণ থেকে আল্লাহর আশ্রয় চাইতেন।", "সহিহ", sourceUrl="https://sunnah.com/bukhari:832"),

        // TRAVEL / WEATHER / FRIDAY
        dua(34, "যানবাহনে ওঠার দোয়া", CATEGORY_TRAVEL,
            "سُبْحَانَ الَّذِي سَخَّرَ لَنَا هَذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ وَإِنَّا إِلَى رَبِّنَا لَمُنْقَلِبُونَ",
            "সুবহানাল্লাযী সাখখারা লানা হাযা, ওয়া মা কুন্না লাহু মুকরিনীন, ওয়া ইন্না ইলা রব্বিনা লামুনকালিবূন।",
            "পবিত্র তিনি, যিনি এ বাহনকে আমাদের অনুগত করেছেন; আমরা নিজেরা একে বশীভূত করতে সক্ষম ছিলাম না। নিশ্চয়ই আমরা আমাদের রবের কাছেই ফিরে যাব।",
            "কুরআন ৪৩:১৩-১৪; সহিহ মুসলিম ১৩৪২", "যানবাহনে ওঠার সময়", "১ বার", "সফরের দোয়ার অংশ হিসেবে পড়া হয়; এরপর পূর্ণ সফরের দোয়া রয়েছে।", "কুরআনের আয়াত; সহিহ মুসলিমে সফরের দোয়া", sourceUrl="https://quran.com/43/13"),
        dua(35, "বৃষ্টি শুরু হলে দোয়া", CATEGORY_WEATHER,
            "اللَّهُمَّ صَيِّبًا نَافِعًا",
            "আল্লাহুম্মা সাইয়্যিবান নাফি‘আ।",
            "হে আল্লাহ! উপকারী বৃষ্টি দান কর।",
            "সহিহ বুখারি ১০৩২", "বৃষ্টি শুরু হলে", "১ বার বা দোয়া হিসেবে", "বৃষ্টি শুরু হলে নবী ﷺ এ দোয়া বলতেন।", "সহিহ", sourceUrl="https://sunnah.com/bukhari:1032"),
        dua(36, "অতিরিক্ত বৃষ্টি হলে দোয়া", CATEGORY_WEATHER,
            "اللَّهُمَّ حَوَالَيْنَا وَلَا عَلَيْنَا",
            "আল্লাহুম্মা হাওয়ালাইনা ওয়া লা আলাইনা।",
            "হে আল্লাহ! আমাদের চারপাশে বৃষ্টি দাও, আমাদের ওপর (ক্ষতিকরভাবে) নয়।",
            "সহিহ বুখারি ১০১৪", "অতিবৃষ্টি ও ক্ষতির আশঙ্কায়", "দোয়া হিসেবে", "নবী ﷺ অতিবৃষ্টির সময় এ দোয়া করেছিলেন।", "সহিহ", sourceUrl="https://sunnah.com/bukhari:1014"),

        // NAFIL PRAYER / TAHAJJUD / ISTIKHARA
        dua(38, "বারো রাকাত সুন্নাতে রাতিবা", CATEGORY_NAFL,
            translation="প্রতিদিন ফরজের সঙ্গে নিয়মিত ১২ রাকাত সুন্নাত: যোহরের আগে ৪, পরে ২; মাগরিবের পরে ২; এশার পরে ২; ফজরের আগে ২—এ বিষয়ে সহিহ বর্ণনা আছে। মাযহাবভেদে আমলের বিন্যাসে কিছু পার্থক্য থাকতে পারে।",
            reference="সহিহ মুসলিম ৭২৮; জামে তিরমিযি ৪১৫", whenToRead="পাঁচ ওয়াক্ত ফরজ সালাতের আগে-পরে", repeatCount="মোট ১২ রাকাত", virtue="যে ব্যক্তি দিনে-রাতে ১২ রাকাত নিয়মিত পড়ে, তার জন্য জান্নাতে ঘর নির্মাণের সুসংবাদ এসেছে।", grade="সহিহ", contentType="GUIDE", sourceUrl="https://sunnah.com/muslim:728"),
        dua(39, "তাহাজ্জুদ ও রাতের সালাত", CATEGORY_TAHAJJUD,
            translation="ইশার পর থেকে ফজরের আগে পর্যন্ত রাতের নফল সালাত আদায় করা যায়। সাধারণভাবে দুই রাকাত করে সালাত আদায় করা হয়। শেষ রাতে দোয়া ও ইস্তিগফারে যত্ন নেওয়া উত্তম। নির্দিষ্ট রাকাতসংখ্যা বাধ্যতামূলক নয়।",
            reference="সহিহ বুখারি ৯৯০; সহিহ মুসলিম ৭৪৯", whenToRead="ইশার পর থেকে সুবহে সাদিকের আগে; শেষ রাত উত্তম", repeatCount="২ রাকাত করে", virtue="রাতের সালাত দুই রাকাত করে আদায়ের নির্দেশ এসেছে।", grade="সহিহ", contentType="GUIDE", sourceUrl="https://sunnah.com/bukhari:990"),
        dua(40, "বিতরের কুনুতের দোয়া", CATEGORY_TAHAJJUD,
            "اللَّهُمَّ اهْدِنِي فِيمَنْ هَدَيْتَ وَعَافِنِي فِيمَنْ عَافَيْتَ وَتَوَلَّنِي فِيمَنْ تَوَلَّيْتَ وَبَارِكْ لِي فِيمَا أَعْطَيْتَ وَقِنِي شَرَّ مَا قَضَيْتَ",
            "আল্লাহুম্মাহদিনী ফীমান হাদাইতা, ওয়া আফিনী ফীমান আফাইতা, ওয়া তাওয়াল্লানী ফীমান তাওয়াল্লাইতা, ওয়া বারিক লী ফীমা আ‘তাইতা, ওয়া কিনী শাররা মা কাদাইতা।",
            "হে আল্লাহ! যাদের হেদায়াত দিয়েছ তাদের সঙ্গে আমাকেও হেদায়াত দাও; যাদের নিরাপত্তা দিয়েছ তাদের সঙ্গে আমাকেও নিরাপদ রাখ; যাদের অভিভাবক হয়েছ তাদের সঙ্গে আমাকেও অভিভাবকত্ব দাও; যা দিয়েছ তাতে বরকত দাও এবং নির্ধারিত অনিষ্ট থেকে রক্ষা কর।",
            "সুনান আবু দাউদ ১৪২৫; জামে তিরমিযি ৪৬৪", "বিতরের কুনুতে", "কুনুতের সময়", "কুনুতের দোয়ার একটি বর্ণিত রূপ।", "হাসান/সহিহ হিসেবে গ্রেডকৃত", sourceUrl="https://sunnah.com/abudawud:1425"),
        dua(41, "ইস্তিখারার নামাজের নিয়ম", CATEGORY_ISTIKHARA,
            translation="কোনো বৈধ বিষয়ে সিদ্ধান্তের আগে ফরজ নয়—এমন দুই রাকাত নফল সালাত পড়ে ইস্তিখারার দোয়া করতে হয়। দোয়ায় ‘হাযাল আমরা’ অংশে নিজের নির্দিষ্ট বিষয়টি মনে করবে/উল্লেখ করবে। স্বপ্ন দেখা ইস্তিখারার শর্ত নয়; পরামর্শ ও বৈধ উপায় অবলম্বনও করবে।",
            reference="সহিহ বুখারি ১১৬৬", whenToRead="বৈধ বিষয়ে সিদ্ধান্তের প্রয়োজন হলে", repeatCount="২ রাকাত নফল; এরপর ইস্তিখারার দোয়া", virtue="নবী ﷺ সাহাবিদের গুরুত্বপূর্ণ বিষয়ে ইস্তিখারা শেখাতেন।", grade="সহিহ", contentType="GUIDE", sourceUrl="https://sunnah.com/bukhari:1166"),

        // FASTING / RAMADAN
        dua(42, "সোমবার ও বৃহস্পতিবার নফল রোজা", CATEGORY_FASTING,
            translation="সোমবার ও বৃহস্পতিবার রোজা রাখার ফজিলত সম্পর্কে হাদিস এসেছে। রোজার নিয়ত অন্তরের কাজ; নির্দিষ্ট আরবি বাক্য উচ্চারণকে আবশ্যক মনে করা যাবে না।",
            reference="সহিহ মুসলিম ১১৬২; সুনান আবু দাউদ ২৪৫১", whenToRead="সোমবার ও বৃহস্পতিবার", repeatCount="সামর্থ্য অনুযায়ী", virtue="সোমবারের রোজা সম্পর্কে নবী ﷺ বলেছেন, এ দিনে তিনি জন্মগ্রহণ করেন এবং তাঁর ওপর ওহি নাজিল হয়।", grade="সহিহ/হাসান বর্ণনা", contentType="GUIDE", sourceUrl="https://sunnah.com/muslim:1162"),
        dua(43, "প্রতি মাসে তিন দিন রোজা", CATEGORY_FASTING,
            translation="প্রতি মাসে তিন দিন নফল রোজা রাখার উৎসাহ হাদিসে এসেছে। আইয়ামে বীয—চান্দ্র মাসের ১৩, ১৪ ও ১৫ তারিখ—রোজার প্রচলিত উত্তম সময়।",
            reference="সহিহ মুসলিম ১১৬২; সহিহ বুখারি ১৯৭৫", whenToRead="প্রতি হিজরি মাসে", repeatCount="৩ দিন", virtue="প্রতি মাসে তিন দিন রোজার ফজিলত বর্ণিত হয়েছে।", grade="সহিহ", contentType="GUIDE", sourceUrl="https://sunnah.com/muslim:1162"),
        dua(44, "আরাফার দিনের রোজা", CATEGORY_FASTING,
            translation="হজে আরাফাতে অবস্থানরত নয়—এমন ব্যক্তির জন্য ৯ জিলহজ আরাফার দিনের রোজার ফজিলত বর্ণিত হয়েছে। হজ পালনকারীর জন্য আরাফাতে রোজা না রাখার সুন্নাহও বর্ণিত।",
            reference="সহিহ মুসলিম ১১৬২", whenToRead="৯ জিলহজ", repeatCount="১ দিন", virtue="আগের ও পরের এক বছরের গুনাহ মোচনের আশা সম্পর্কে হাদিস এসেছে (সগিরা গুনাহের ক্ষেত্রে আলেমদের ব্যাখ্যা প্রযোজ্য)।", grade="সহিহ", contentType="GUIDE", sourceUrl="https://sunnah.com/muslim:1162"),
        dua(45, "আশুরার রোজা", CATEGORY_FASTING,
            translation="১০ মুহাররম আশুরার রোজা রাখা সুন্নাহ। ইহুদিদের সঙ্গে পার্থক্য করার জন্য এর সঙ্গে ৯ বা ১১ মুহাররমও রোজা রাখার ইচ্ছা/আমল বর্ণিত হয়েছে; এ বিষয়ে আলেমদের ব্যাখ্যা রয়েছে।",
            reference="সহিহ মুসলিম ১১৩৪; সহিহ বুখারি ২০০৪", whenToRead="১০ মুহাররম; ৯ বা ১১-ও যোগ করা যায়", repeatCount="১–২ দিন", virtue="আশুরার রোজা আগের এক বছরের গুনাহ মোচনের কারণ হয়—এ মর্মে সহিহ মুসলিমে এসেছে।", grade="সহিহ", contentType="GUIDE", sourceUrl="https://sunnah.com/muslim:1134"),
        dua(46, "শাওয়ালের ছয় রোজা", CATEGORY_FASTING,
            translation="রমজানের রোজার পর শাওয়াল মাসে ছয় দিন রোজা রাখার ফজিলত রয়েছে। ধারাবাহিক বা বিরতি দিয়ে রাখা যায়—এ বিষয়ে ফিকহি ব্যাখ্যা আছে।",
            reference="সহিহ মুসলিম ১১৬৪", whenToRead="১ শাওয়াল (ঈদের দিন) বাদে শাওয়াল মাসে", repeatCount="৬ দিন", virtue="রমজানের পর ছয় দিন শাওয়াল রোজা রাখলে পূর্ণ বছর রোজার সওয়াবের মতো হওয়ার কথা এসেছে।", grade="সহিহ", contentType="GUIDE", sourceUrl="https://sunnah.com/muslim:1164"),
        dua(47, "লাইলাতুল কদরের দোয়া", CATEGORY_RAMADAN,
            "اللَّهُمَّ إِنَّكَ عَفُوٌّ تُحِبُّ الْعَفْوَ فَاعْفُ عَنِّي",
            "আল্লাহুম্মা ইন্নাকা আফুউউন, তুহিব্বুল আফওয়া, ফা‘ফু আন্নী।",
            "হে আল্লাহ! নিশ্চয়ই তুমি পরম ক্ষমাশীল, ক্ষমা করতে ভালোবাস; তাই আমাকে ক্ষমা কর।",
            "জামে তিরমিযি ৩৫১৩; সুনান ইবনে মাজাহ ৩৮৫০", "বিশেষত শেষ দশকের বেজোড় রাতে", "যতবার ইচ্ছা", "আয়িশা (রা.) লাইলাতুল কদরে কী দোয়া করবেন জিজ্ঞেস করলে নবী ﷺ এটি শিখিয়েছেন।", "হাসান সহিহ হিসেবে গ্রেডকৃত", sourceUrl="https://sunnah.com/tirmidhi:3513"),
        dua(48, "সাহরি ও ইফতারের আদব", CATEGORY_RAMADAN,
            translation="সাহরি খাওয়া বরকতময় সুন্নাহ। সূর্যাস্ত নিশ্চিত হলে দ্রুত ইফতার করা সুন্নাহ। ইফতারের জন্য নির্দিষ্ট একটি বাক্যকে বাধ্যতামূলক বা একমাত্র সহিহ দোয়া বলা ঠিক নয়; নিজের ভাষায়ও দোয়া করা যায়।",
            reference="সহিহ বুখারি ১৯২৩; সহিহ মুসলিম ১০৯৫", whenToRead="সাহরির সময় ও সূর্যাস্তের পর", repeatCount="প্রতি রোজায়", virtue="সাহরিতে বরকত এবং সময়মতো ইফতারের নির্দেশ হাদিসে এসেছে।", grade="সহিহ", contentType="GUIDE", sourceUrl="https://sunnah.com/bukhari:1923"),

        // HAJJ / DECEASED / HADITH / CHARITY
        dua(49, "হজ ও উমরার তালবিয়া", CATEGORY_HAJJ,
            "لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ، لَبَّيْكَ لَا شَرِيكَ لَكَ لَبَّيْكَ، إِنَّ الْحَمْدَ وَالنِّعْمَةَ لَكَ وَالْمُلْكَ، لَا شَرِيكَ لَكَ",
            "লাব্বাইকাল্লাহুম্মা লাব্বাইক, লাব্বাইকা লা শারীকা লাকা লাব্বাইক। ইন্নাল হামদা ওয়ান নি‘মাতা লাকা ওয়াল মুলক, লা শারীকা লাক।",
            "আমি হাজির, হে আল্লাহ, আমি হাজির। তোমার কোনো শরিক নেই, আমি হাজির। নিশ্চয়ই সব প্রশংসা, নিয়ামত ও রাজত্ব তোমারই; তোমার কোনো শরিক নেই।",
            "সহিহ বুখারি ১৫৪৯; সহিহ মুসলিম ১১৮৪", "ইহরাম বাঁধার পর হজ/উমরার তালবিয়া", "বারবার", "তালবিয়া হজ ও উমরার গুরুত্বপূর্ণ শিআর।", "সহিহ", sourceUrl="https://sunnah.com/bukhari:1549"),
        dua(50, "মৃত ব্যক্তির জন্য জানাজার দোয়া", CATEGORY_DECEASED,
            "اللَّهُمَّ اغْفِرْ لَهُ وَارْحَمْهُ وَعَافِهِ وَاعْفُ عَنْهُ",
            "আল্লাহুম্মাগফির লাহু, ওয়ারহামহু, ওয়া আফিহি, ওয়াফু আনহু।",
            "হে আল্লাহ! তাকে ক্ষমা কর, তার প্রতি দয়া কর, তাকে নিরাপত্তা দাও এবং তাকে মার্জনা কর। (মৃত নারী হলে ‘লাহু’ এর স্থলে ‘লাহা’ বলা হবে।)",
            "সহিহ মুসলিম ৯৬৩", "জানাজার সালাতে মৃত ব্যক্তির জন্য দোয়া", "দোয়ার অংশ", "জানাজার দোয়ায় মৃতের জন্য ক্ষমা ও রহমত চাওয়া হয়।", "সহিহ", sourceUrl="https://sunnah.com/muslim:963"),
        dua(51, "নিয়তের গুরুত্ব", CATEGORY_HADITH,
            translation="রাসুলুল্লাহ ﷺ বলেছেন: কাজের ফল নিয়তের ওপর নির্ভরশীল; প্রত্যেক ব্যক্তি তাই পাবে যা সে নিয়ত করেছে।",
            reference="সহিহ বুখারি ১; সহিহ মুসলিম ১৯০৭", whenToRead="ইবাদত ও কাজের আগে নিয়ত শুদ্ধ করা", virtue="ইসলামের মৌলিক নীতিগুলোর একটি।", grade="সহিহ", contentType="HADITH", sourceUrl="https://sunnah.com/bukhari:1"),
        dua(52, "প্রতিবেশী ও অতিথির হক", CATEGORY_HADITH,
            translation="যে আল্লাহ ও আখিরাতে বিশ্বাস করে, সে যেন তার প্রতিবেশীকে কষ্ট না দেয়; অতিথিকে সম্মান করে এবং ভালো কথা বলে অথবা চুপ থাকে।",
            reference="সহিহ বুখারি ৬০১৮; সহিহ মুসলিম ৪৭", whenToRead="দৈনন্দিন আচরণে", virtue="সুন্দর চরিত্র ও সামাজিক অধিকারের শিক্ষা।", grade="সহিহ", contentType="HADITH", sourceUrl="https://sunnah.com/bukhari:6018"),
        dua(53, "যাকাত ও সদকার মূলনীতি", CATEGORY_CHARITY,
            translation="যাকাত ফরজ হওয়ার শর্ত, নিসাব, সম্পদের ধরন ও হাওল বিষয়ে নির্ভরযোগ্য আলেমের কাছ থেকে নিজের অবস্থার বিধান জেনে নিতে হবে। সদকা গোপনে বা প্রকাশ্যে দেওয়া যায়; লোকদেখানো ও খোঁটা দেওয়া থেকে বিরত থাকতে হবে।",
            reference="কুরআন ৯:৬০; ২:২৬১–২৬৪", whenToRead="যাকাতের হিসাবের সময় ও সদকা দেওয়ার ক্ষেত্রে", virtue="দান-সদকার বিধান ও আদব কুরআনে বর্ণিত।", grade="কুরআনের আয়াত; বিস্তারিত ফিকহি বিধান আলাদা", contentType="GUIDE", sourceUrl="https://quran.com/9/60"),
        dua(54, "হাঁচি দেওয়ার পর আলহামদুলিল্লাহ বলা", CATEGORY_DAILY,
            "الْحَمْدُ لِلَّهِ",
            "আলহামদু লিল্লাহ।",
            "সমস্ত প্রশংসা আল্লাহর। হাঁচি দেওয়ার পর হাঁচিদাতা ‘আলহামদুলিল্লাহ’ বলবে; শ্রোতা ‘ইয়ারহামুকাল্লাহ’ বলবে; এরপর হাঁচিদাতা ‘ইয়াহদীকুমুল্লাহু ওয়া ইউসলিহু বালাকুম’ বলবে।",
            "সহিহ বুখারি ৬২২৪; সহিহ মুসলিম ২৯৯১", "হাঁচি দেওয়ার পর", "প্রতি হাঁচির পর আদব অনুযায়ী", "হাঁচির পর পারস্পরিক দোয়া ও জবাবের আদব হাদিসে এসেছে।", "সহিহ", sourceUrl="https://sunnah.com/bukhari:6224"),
        dua(56, "ইস্তিখারার পূর্ণ দোয়া", CATEGORY_ISTIKHARA,
            "اللَّهُمَّ إِنِّي أَسْتَخِيرُكَ بِعِلْمِكَ وَأَسْتَقْدِرُكَ بِقُدْرَتِكَ وَأَسْأَلُكَ مِنْ فَضْلِكَ الْعَظِيمِ فَإِنَّكَ تَقْدِرُ وَلَا أَقْدِرُ وَتَعْلَمُ وَلَا أَعْلَمُ وَأَنْتَ عَلَّامُ الْغُيُوبِ اللَّهُمَّ إِنْ كُنْتَ تَعْلَمُ أَنَّ هَذَا الْأَمْرَ خَيْرٌ لِي فِي دِينِي وَمَعَاشِي وَعَاقِبَةِ أَمْرِي فَاقْدُرْهُ لِي وَيَسِّرْهُ لِي ثُمَّ بَارِكْ لِي فِيهِ وَإِنْ كُنْتَ تَعْلَمُ أَنَّ هَذَا الْأَمْرَ شَرٌّ لِي فِي دِينِي وَمَعَاشِي وَعَاقِبَةِ أَمْرِي فَاصْرِفْهُ عَنِّي وَاصْرِفْنِي عَنْهُ وَاقْدُرْ لِيَ الْخَيْرَ حَيْثُ كَانَ ثُمَّ أَرْضِنِي بِهِ",
            "আল্লাহুম্মা ইন্নী আসতাখীরুকা বি ইলমিকা, ওয়া আসতাকদিরুকা বি কুদরাতিকা, ওয়া আসআলুকা মিন ফাদলিকাল আযীম। ফা ইন্নাকা তাকদিরু ওয়া লা আকদির, ওয়া তা‘লামু ওয়া লা আ‘লাম, ওয়া আন্তা আল্লামুল গুয়ূব। আল্লাহুম্মা ইন কুনতা তা‘লামু আন্না হাযাল আমরা খাইরুল লী ফী দীনী ওয়া মা‘আশী ওয়া আকিবাতি আমরী, ফাকদুরহু লী ওয়া ইয়াসসিরহু লী, ছুম্মা বারিক লী ফীহি। ওয়া ইন কুনতা তা‘লামু আন্না হাযাল আমরা শাররুল লী ফী দীনী ওয়া মা‘আশী ওয়া আকিবাতি আমরী, ফাসরিফহু আন্নী ওয়াসরিফনী আনহু, ওয়াকদুর লিয়াল খাইরা হাইছু কানা, ছুম্মা আরদিনী বিহি।",
            "হে আল্লাহ! তোমার জ্ঞানের মাধ্যমে তোমার কাছে কল্যাণ চাই, তোমার ক্ষমতার মাধ্যমে সামর্থ্য চাই এবং তোমার মহান অনুগ্রহ চাই। তুমি সক্ষম, আমি অক্ষম; তুমি জান, আমি জানি না; তুমি অদৃশ্যের জ্ঞানী। এ বিষয়টি আমার দ্বীন, জীবিকা ও পরিণামের জন্য ভালো হলে তা নির্ধারণ, সহজ ও বরকতময় কর। খারাপ হলে তা আমার থেকে এবং আমাকে তা থেকে ফিরিয়ে দাও; যেখানেই কল্যাণ থাকুক তা নির্ধারণ কর এবং তাতে আমাকে সন্তুষ্ট কর। ‘হাযাল আমরা’ বলার সময় নিজের বিষয়টি মনে করবে।",
            "সহিহ বুখারি ১১৬৬", "দুই রাকাত নফল সালাতের পর", "একবার দোয়া", "নবী ﷺ সাহাবিদের সব বিষয়ে ইস্তিখারা শেখাতেন। স্বপ্ন দেখা এর শর্ত নয়।", "সহিহ", sourceUrl="https://sunnah.com/bukhari:1166"),
        dua(57, "ঈমান, ক্ষমা ও জাহান্নাম থেকে রক্ষার রব্বানা দোয়া", CATEGORY_RABBANA,
            "رَبَّنَا إِنَّنَا آمَنَّا فَاغْفِرْ لَنَا ذُنُوبَنَا وَقِنَا عَذَابَ النَّارِ",
            "রব্বানা ইন্নানা আমান্না, ফাগফির লানা যুনুবানা, ওয়া কিনা আযাবান্নার।",
            "হে আমাদের রব! আমরা ঈমান এনেছি; অতএব আমাদের গুনাহ ক্ষমা কর এবং আগুনের শাস্তি থেকে রক্ষা কর।",
            "কুরআন ৩:১৬", "দোয়ার সময়", "যেকোনো সময়", "কুরআনে মুমিনদের দোয়া হিসেবে এসেছে।", "কুরআনের আয়াত", sourceUrl="https://quran.com/3/16")
    )

    // সংশোধিত ও নতুন এন্ট্রি একত্র করে ক্যাটাগরি অনুযায়ী সাজানো তালিকা
    val getDuasAndHadiths: List<DuaItem> by lazy {
        val fixed = DuaFixes.items
        val fixedIds = fixed.map { it.id }.toSet()
        (baseDuas.filter { it.id !in fixedIds } + fixed +
            DuaMore1.items + DuaMore2.items + DuaMore3.items +
            DuaMore4.items + DuaMore5.items)
            .sortedWith(compareBy({ getCategories.indexOf(it.category) }, { it.id }))
    }
}
